module Texture

// Texture decode/upload + PBR material. Textures are decoded from disk by
// SDL_image (IMG_Load) into a software surface, then uploaded into an SDL_gpu
// sampled texture with a full mip chain generated by SDL. A `Material` bundles the metallic-roughness
// factors with up to four texture samplers (albedo/normal/metallic-roughness/
// emissive); absent maps fall back to a shared white placeholder and are skipped
// by the shader's has* flags.

open System
open System.Diagnostics
open System.IO
open System.Numerics
open System.Runtime.InteropServices
open SDL3
open Gpu

// A decoded image uploaded as an SDL_gpu texture + sampler.
[<Struct>]
type Texture =
    { Device : Gpu.Device
      Handle : Gpu.Texture
      Sampler : Gpu.Sampler
      // The GPU bytes this texture occupies: level 0 (`W*H*4`) plus its mip chain (~4/3 of
      // that). Captured at load so the residency budget can be accounted without re-reading
      // dimensions; the 1x1 placeholder is 4.
      Bytes : int64 }

// Scene lighting: a directional sun + ambient. Shared by both pipelines.
[<Struct>]
type Light =
    { Direction : Vector3   // toward the sun
      Color : Vector3
      Ambient : Vector3 }

// A zone's authored sun (spec 043): the four values `odin-game` stores on a zone
// (`src/zone_registry.odin`). `Pitch` is degrees above the horizon (0 = horizon, 90 = zenith) and
// `Yaw` is compass degrees; the ambient is a single intensity. `toLight` resolves these into the
// shader-facing `Light` above.
[<Struct>]
type LightSettings =
    { Pitch : float32
      Yaw : float32
      Color : Vector3
      Ambient : float32 }

// The light in use before spec 043, expressed as angles: the pitch and yaw of the direction
// `normalize(0.4, 0.8, 0.4)` (`asin(0.8 / sqrt(0.96))`, `atan2(0.4, 0.4)`), with the same white
// colour and a neutral `0.15` ambient. A zone that has never been edited therefore lights exactly
// as it did (FR-004).
let defaultLight : LightSettings =
    { Pitch = 54.7356f
      Yaw = 45.0f
      Color = Vector3(1.0f, 1.0f, 1.0f)
      Ambient = 0.15f }

// Resolve a zone's authored settings into the shader-facing light (FR-008). The direction is
// `odin-game`'s spherical convention — `{sin yaw·cos pitch, sin pitch, cos yaw·cos pitch}` — so a
// pitch and yaw mean the same thing in both games; the scalar ambient expands to the port's neutral
// grey, which is what keeps an unedited scene identical to the constant it replaces.
let toLight (settings: LightSettings) : Light =
    let pitch = settings.Pitch * (float32 System.Math.PI / 180.0f)
    let yaw = settings.Yaw * (float32 System.Math.PI / 180.0f)
    let sinPitch = sin pitch
    let cosPitch = cos pitch
    let direction = Vector3.Normalize(Vector3(sin yaw * cosPitch, sinPitch, cos yaw * cosPitch))
    { Direction = direction
      Color = settings.Color
      Ambient = Vector3(settings.Ambient, settings.Ambient, settings.Ambient) }

// Runtime PBR material. `Bindings` is always four entries in fixed shader order
// (albedo, normal, metallicRoughness, emissive); absent slots use the shared
// white placeholder and are skipped via the has* flags.
type Material =
    { BaseColor : Vector4
      Metallic : float32
      Roughness : float32
      Emissive : Vector3
      HasAlbedo : bool
      HasNormal : bool
      HasMetallicRoughness : bool
      HasEmissive : bool
      Bindings : SDL.GPUTextureSamplerBinding array }

let private createSampler (device: Gpu.Device) : Gpu.Sampler =
    let mutable info = SDL.GPUSamplerCreateInfo()
    info.MinFilter <- SDL.GPUFilter.Linear
    info.MagFilter <- SDL.GPUFilter.Linear
    info.MipmapMode <- SDL.GPUSamplerMipmapMode.Linear
    info.AddressModeU <- SDL.GPUSamplerAddressMode.Repeat
    info.AddressModeV <- SDL.GPUSamplerAddressMode.Repeat
    info.AddressModeW <- SDL.GPUSamplerAddressMode.Repeat
    SDL.CreateGPUSampler(device, &info)

// Wrap a Texture as a texture+sampler binding (fixed shader slot).
let private binding (t: Texture) : SDL.GPUTextureSamplerBinding =
    let mutable b = SDL.GPUTextureSamplerBinding()
    b.Texture <- t.Handle
    b.Sampler <- t.Sampler
    b

// libSDL3_image (vendored next to the apphost) links libjbig.so.0 for TIFF/JBIG
// support. Preload it from the app directory before the first decode: the app
// dir is not in the dynamic linker's default search path, so this makes
// libjbig.so.0 resolvable when SDL_image is first dlopen'd.
let private preloadImageDep = lazy (
    let path = Path.Combine(AppContext.BaseDirectory, "libjbig.so.0")
    if File.Exists(path) then NativeLibrary.Load(path) |> ignore)

// ── texture instrumentation (spec 052 FR-008; spec 053 T008) ──
// Creation cost only: decode happens on a worker and its timing rides `DecodedImage.DecodeNs`, so no
// worker writes a process-global. Reset/read by the loader around an asset build (render thread).
type TextureLoadStats =
    { mutable CreateNs : int64
      mutable Creates : int }

let mutable private stats = { CreateNs = 0L; Creates = 0 }
let resetLoadStats () : unit = stats <- { CreateNs = 0L; Creates = 0 }
let loadStats () : TextureLoadStats = stats

// The CPU-side result of decoding one image: compacted RGBA8 rows and the decode cost. Produced on a
// worker by `decode`; consumed on the render thread by `createFromDecoded`. Declared here (not in
// `world/assets/AssetLoad.fs`) because `Texture.decode` returns it and `Texture.fs` is compiled first.
[<Struct>]
type DecodedImage =
    { Width : int
      Height : int
      Pixels : byte array   // Width*4*Height, rows compacted (no pitch padding)
      DecodeNs : int64 }

// Decode an image file to compacted RGBA8, CPU-only (worker-safe): no device, no batch. SDL_image
// reads it and, when needed, `ConvertSurface` normalises to ABGR8888 (bytes R,G,B,A little-endian).
// Raises on a missing/corrupt file; the worker turns that into a `LoadFailed`.
let decode (path: string) : DecodedImage =
    let t0 = Stopwatch.GetTimestamp()
    do preloadImageDep.Value
    let decoded = SDL3.Image.Load(path)
    if decoded = IntPtr.Zero then failwithf "texture: failed to load '%s'" path

    let decodedInfo = Marshal.PtrToStructure<SDL.Surface>(decoded)
    let surface =
        if decodedInfo.Format = SDL.PixelFormat.ABGR8888 then decoded else
        let converted = SDL.ConvertSurface(decoded, SDL.PixelFormat.ABGR8888)
        if converted = IntPtr.Zero then failwithf "texture: failed to convert '%s'" path
        do SDL.DestroySurface(decoded)
        converted
    let s = Marshal.PtrToStructure<SDL.Surface>(surface)

    // Compact the rows (Pitch may exceed Width*4) into one level-0 image.
    let rowBytes = s.Width * 4
    let packed = Array.zeroCreate<byte> (rowBytes * s.Height)
    for y in 0 .. s.Height - 1 do
        do Marshal.Copy(IntPtr.Add(s.Pixels, y * s.Pitch), packed, y * rowBytes, rowBytes)
    do SDL.DestroySurface(surface)
    { Width = s.Width; Height = s.Height; Pixels = packed; DecodeNs = Stopwatch.GetTimestamp() - t0 }

// Create the GPU texture + full mip chain from decoded pixels and record the level-0 upload into
// `batch` (spec 052). Render thread only. The `Bytes` accounting is identical to the pre-053 `load`.
let createFromDecoded (batch: Gpu.UploadBatch) (device: Gpu.Device) (image: DecodedImage) : Texture =
    let c0 = Stopwatch.GetTimestamp()
    let levels = uint32 (int (MathF.Log2(float32 (max image.Width image.Height)))) + 1u
    let mutable info = SDL.GPUTextureCreateInfo()
    info.Type <- SDL.GPUTextureType.TextureType2D
    info.Format <- SDL.GPUTextureFormat.R8G8B8A8Unorm
    info.Usage <- SDL.GPUTextureUsageFlags.Sampler ||| SDL.GPUTextureUsageFlags.ColorTarget
    info.Width <- uint32 image.Width
    info.Height <- uint32 image.Height
    info.LayerCountOrDepth <- 1u
    info.NumLevels <- levels
    info.SampleCount <- SDL.GPUSampleCount.SampleCount1
    let handle = SDL.CreateGPUTexture(device, &info)
    if handle = IntPtr.Zero then failwith "texture: failed to create GPU texture"
    let sampler = createSampler device
    stats.CreateNs <- stats.CreateNs + (Stopwatch.GetTimestamp() - c0)
    stats.Creates <- stats.Creates + 1

    Gpu.recordTexture batch handle image.Pixels (uint32 image.Width) (uint32 image.Height) levels

    { Device = device
      Handle = handle
      Sampler = sampler
      Bytes = int64 image.Width * int64 image.Height * 4L * 4L / 3L }

// A 1x1 solid RGBA texture (used as the shared placeholder for absent maps).
let solid (device: Gpu.Device) (r: byte) (g: byte) (b: byte) (a: byte) : Texture =
    let mutable texInfo = SDL.GPUTextureCreateInfo()
    texInfo.Type <- SDL.GPUTextureType.TextureType2D
    texInfo.Format <- SDL.GPUTextureFormat.R8G8B8A8Unorm
    texInfo.Usage <- SDL.GPUTextureUsageFlags.Sampler
    texInfo.Width <- 1u
    texInfo.Height <- 1u
    texInfo.LayerCountOrDepth <- 1u
    texInfo.NumLevels <- 1u
    texInfo.SampleCount <- SDL.GPUSampleCount.SampleCount1
    let handle = SDL.CreateGPUTexture(device, &texInfo)

    let transfer = Gpu.createTransferBuffer device 4u
    let mapped = SDL.MapGPUTransferBuffer(device, transfer, false)
    let pixels = [| r; g; b; a |]
    Marshal.Copy(pixels, 0, mapped, 4)
    SDL.UnmapGPUTransferBuffer(device, transfer)

    let cmd = SDL.AcquireGPUCommandBuffer(device)
    let copyPass = SDL.BeginGPUCopyPass(cmd)
    let mutable transferInfo = SDL.GPUTextureTransferInfo()
    transferInfo.TransferBuffer <- transfer
    transferInfo.Offset <- 0u
    let mutable region = SDL.GPUTextureRegion()
    region.Texture <- handle
    region.MipLevel <- 0u
    region.Layer <- 0u
    region.X <- 0u
    region.Y <- 0u
    region.Z <- 0u
    region.W <- 1u
    region.H <- 1u
    region.D <- 1u
    SDL.UploadToGPUTexture(copyPass, &transferInfo, &region, false)
    SDL.EndGPUCopyPass(copyPass)
    SDL.SubmitGPUCommandBuffer(cmd) |> ignore
    SDL.ReleaseGPUTransferBuffer(device, transfer)

    { Device = device; Handle = handle; Sampler = createSampler device; Bytes = 4L }

// Release a texture's sampler and its GPU image. Created together, owned together:
// every texture is freed through here so no owner has to know the SDL calls.
let release (t: Texture) : unit =
    if t.Sampler <> IntPtr.Zero then SDL.ReleaseGPUSampler(t.Device, t.Sampler)
    if t.Handle <> IntPtr.Zero then SDL.ReleaseGPUTexture(t.Device, t.Handle)

// Build a runtime material; `white` is the shared placeholder substituted for
// absent maps so the four sampler bindings stay contiguous.
let makeMaterial
    (white: Texture)
    (baseColor: Vector4)
    (metallic: float32)
    (roughness: float32)
    (emissive: Vector3)
    (albedo: Texture option)
    (normal: Texture option)
    (metallicRoughness: Texture option)
    (emissiveTex: Texture option) : Material =
    let pick (t: Texture option) : Texture * bool =
        match t with Some x -> (x, true) | None -> (white, false)
    let (a, hasA) = pick albedo
    let (n, hasN) = pick normal
    let (mr, hasMR) = pick metallicRoughness
    let (e, hasE) = pick emissiveTex
    let bindings =
        [| binding a
           binding n
           binding mr
           binding e |]
    { BaseColor = baseColor
      Metallic = metallic
      Roughness = roughness
      Emissive = emissive
      HasAlbedo = hasA
      HasNormal = hasN
      HasMetallicRoughness = hasMR
      HasEmissive = hasE
      Bindings = bindings }

// A default dielectric material (no maps, sensible roughness).
let defaultMaterial (white: Texture) (baseColor: Vector4) : Material =
    makeMaterial white baseColor 0.0f 0.8f Vector3.Zero None None None None
